package com.ferreteriahuaman.integration;
import com.ferreteriahuaman.service.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.dto.CustomerModels.*;import com.ferreteriahuaman.dto.CatalogModels.StateInput;import com.ferreteriahuaman.security.AuthModels.Identity;import com.ferreteriahuaman.security.AuthFailure;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="HUAMAN_DB_INTEGRATION",matches="true")
class CustomerDatabaseTest {
 @Autowired CustomerService service;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;Identity actor;String name,doc;
 @BeforeEach void setup(){var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusMinutes(30));name="INTEGRACION_"+UUID.randomUUID();do{doc=String.format("%08d",10000000+new java.security.SecureRandom().nextInt(90000000));}while(jdbc.queryForObject("select exists(select 1 from huaman.cliente where nro_documento=?)",Boolean.class,doc));}
 Input input(String name,LocalDateTime version){return new Input("DNI",doc,name,null,null,null,version);}
 @Test void createLookupEditCreditAndStateAreAudited(){var c=service.save(actor,"INTEGRATION_ROLLBACK",null,input(name,null));assertThat(c.limiteCredito()).isEqualTo("0.00");assertThat(service.lookup(doc).id()).isEqualTo(c.id());assertThat(service.list(name,"A",0,20).total()).isEqualTo(1);c=service.save(actor,"INTEGRATION_ROLLBACK",c.id(),input(name+" Editado",c.version()));c=service.credit(actor,"INTEGRATION_ROLLBACK",c.id(),new Credit(new BigDecimal("500.25"),c.version()));assertThat(c.limiteCredito()).isEqualTo("500.25");c=service.state(actor,"INTEGRATION_ROLLBACK",c.id(),new StateInput("I",c.version()));assertThat(c.estado()).isEqualTo("I");assertThatThrownBy(()->service.lookup(doc)).isInstanceOf(AuthFailure.class);assertThat(jdbc.queryForObject("select count(*) from huaman.bitacora_evento where entidad='cliente' and id_entidad=?",Long.class,c.id())).isEqualTo(4);}
 @Test void staleVersionDoesNotOverwriteData(){var c=service.save(actor,"INTEGRATION_ROLLBACK",null,input(name,null));var changed=service.save(actor,"INTEGRATION_ROLLBACK",c.id(),input(name+" Actual",c.version()));assertThatThrownBy(()->service.save(actor,"INTEGRATION_ROLLBACK",c.id(),input(name+" Obsoleto",c.version().minusSeconds(1)))).isInstanceOf(AuthFailure.class);assertThat(service.get(c.id()).nombre()).isEqualTo(changed.nombre());}
}
